import os
import re
from pathlib import Path

from auto_config.generator.utils.logger import logger
from auto_config.generator.utils.utils import get_yaml_file, merge_dictionaries


def check_path_exists(path, component, name):
    if not os.path.exists(path):
        raise Exception(f"Given {component}={name} does not exist under {os.path.pardir} directory!")


def load_source_files(profile, custom_dir, custom_yaml_map, profile_path=None):

    config_dir = Path(os.path.abspath(__file__)).parents[2] / "config"

    rmods_path = os.path.join(config_dir, "rmods.yaml")
    bbmods_smods_path = os.path.join(config_dir, "bbmods_smods.yaml")

    uecap_config_path = os.path.join(config_dir, "uecap.yaml")
    uecap_path = os.path.join(config_dir, 'uecap.ini')

    default_ue_path = os.path.join(config_dir, "ue.yaml")
    default_ue = get_yaml_file(default_ue_path)

    if profile_path:
        enb_path = os.path.join(profile_path, 'enb.yaml')
        check_path_exists(enb_path, "enb", 'enb.yaml')
        logger.info(f"Using custom enb.yaml from profile_path, path: {enb_path}")

        ue_path = os.path.join(profile_path, 'ue.yaml')
        check_path_exists(ue_path, "ue", 'ue.yaml')
        logger.info(f"Using custom ue.yaml from profile_path, path: {ue_path}")
        profile_ue = get_yaml_file(ue_path)

        hw_path = os.path.join(profile_path, 'hw.yaml')
        check_path_exists(hw_path, "hw", 'hw.yaml')
        logger.info(f"Using custom hw.yaml from profile_path, path: {hw_path}")

        epc_path = os.path.join(profile_path, 'epc.yaml')
        check_path_exists(epc_path, "epc", 'epc.yaml')
        logger.info(f"Using custom epc.yaml from profile_path, path: {epc_path}")

        ue = dict(merge_dictionaries(default_ue, profile_ue))

        paths = {'epc': epc_path, 'enb': enb_path, 'hw': hw_path, 'bbmods_smods': bbmods_smods_path,
                 'rmods': rmods_path, 'uecap_config': uecap_config_path}
        source_files = {k: get_yaml_file(v) for k, v in paths.items()}
        source_files['uecap_ini'] = get_uecap_ini(uecap_path)
        source_files['ue'] = ue

        return source_files

    profile_ue_path = os.path.join(config_dir, "profiles", profile, "ue.yaml")
    profile_ue = get_yaml_file(profile_ue_path)

    env_path = os.path.join(config_dir, "env.yaml")
    ems_path = os.path.join(config_dir, "ems.yaml")

    epc_path = os.path.join(config_dir, "profiles", profile, "epc.yaml")
    enb_path = os.path.join(config_dir, "profiles", profile, "enb.yaml")
    hw_path = os.path.join(config_dir, "profiles", profile, "hw.yaml")

    if custom_dir:
        if not os.path.exists(custom_dir):
            raise Exception(f"Given {custom_dir=} does not exist!")

        enb_filename_match = re.search(r'enb=([^.]*\.yaml)', custom_yaml_map)
        if enb_filename_match:
            enb_path = os.path.join(custom_dir, enb_filename_match.group(1))
            check_path_exists(enb_path, "enb", enb_filename_match.group(1))
            logger.info(f"Using custom enb.yaml, path: {enb_path}")

        bts_filename_match = re.search(r'bts=([^.]*\.yaml)', custom_yaml_map)
        if bts_filename_match:
            enb_path = os.path.join(custom_dir, bts_filename_match.group(1))
            check_path_exists(enb_path, "bts", bts_filename_match.group(1))
            logger.info(f"Using custom BTS yaml, path: {enb_path}")

        epc_filename_match = re.search(r'epc=([^.]*\.yaml)', custom_yaml_map)
        if epc_filename_match:
            epc_path = os.path.join(custom_dir, epc_filename_match.group(1))
            check_path_exists(epc_path, "epc", epc_filename_match.group(1))
            logger.info(f"Using custom epc.yaml, path: {epc_path}")

        env_filename_match = re.search(r'env=([^.]*\.yaml)', custom_yaml_map)
        if env_filename_match:
            env_path = os.path.join(custom_dir, env_filename_match.group(1))
            check_path_exists(env_path, "env", env_filename_match.group(1))
            logger.info(f"Using custom env.yaml, path: {env_path}")

        ue_filename_match = re.search(r'ue=([^.]*\.yaml)', custom_yaml_map)
        if ue_filename_match:
            ue_path = os.path.join(custom_dir, ue_filename_match.group(1))
            profile_ue = get_yaml_file(ue_path)
            check_path_exists(ue_path, "ue", ue_filename_match.group(1))
            logger.info(f"Using custom ue.yaml, path: {ue_path}")

    ue = dict(merge_dictionaries(default_ue, profile_ue))
    paths = {'env': env_path, 'ems': ems_path, 'epc': epc_path, 'enb': enb_path, 'rmods': rmods_path,
             'uecap_config': uecap_config_path, 'hw': hw_path, 'bbmods_smods': bbmods_smods_path}
    source_files = {k: get_yaml_file(v) for k, v in paths.items()}
    source_files['ue'] = ue

    uecap_path = os.path.join(config_dir, 'uecap.ini')
    source_files['uecap_ini'] = get_uecap_ini(uecap_path)
    return source_files


def get_uecap_ini(uecap_path):

    with open(uecap_path, encoding='utf-8', mode='r') as f:
        index, profile = 0, None
        uecap = {}
        for line in f:
            if re.match(r'\s*;', line):
                continue
            if re.match(r'^\s*\[profile\s+(\S+)\s*\]', line.strip()):
                profile_matches = re.match(r'^\s*\[profile\s+(\S+)\s*\]', line.strip())
                index += 1
                profile = profile_matches.group(1)
                uecap[profile] = {'INDEX': index}

            elif re.match(r'^\s*(\S+)\s*=\s*(.*)', line.strip()):
                matches = re.match(r'^\s*(\S+)\s*=\s*(.*)', line.strip())
                attr, value = matches.group(1, 2)
                uecap[profile][attr] = value
        return uecap
